<template><q-page class="customer-flow-page"><div class="page-heading"><div><div class="eyebrow">SIMULATED TRANSFERS</div><h1 class="page-title">Send to another bank</h1><p class="page-subtitle">Funds are debited now. Staff completes or rejects the simulated settlement; rejected transfers are refunded.</p></div><q-btn flat label="Refresh" icon="refresh" @click="load" /></div><q-banner v-if="error" class="bank-feedback q-mb-md">{{ error }}</q-banner><div class="customer-workspace-grid"><section class="customer-panel"><q-form ref="entryForm" class="customer-form" @submit="review = true"><q-select v-model="form.source_account_id" filled label="From account" :options="accounts" emit-value map-options :rules="[required]" /><q-select v-model="form.target_bank_id" filled label="Destination bank" :options="banks" emit-value map-options :rules="[required]" /><q-input v-model.trim="form.target_account_number" filled label="Recipient account number" maxlength="50" :rules="[v => /^[a-zA-Z0-9-]{3,50}$/.test(v) || 'Enter a valid account number']" /><q-input v-model.trim="form.beneficiary_name" filled label="Recipient name" maxlength="150" :rules="[required]" /><q-input v-model="form.amount" filled type="number" min="0.01" step="0.01" label="Amount (PHP)" :rules="[v => Number(v) > 0 || 'Enter a positive amount']" /><p class="page-subtitle">Transfer fee: PHP 0.00. No real bank receives funds.</p><q-btn color="primary" label="Review transfer" type="submit" :disable="loading || busy" /></q-form></section><section class="customer-panel"><h2 class="section-heading">Other-bank history</h2><q-table flat :rows="rows" :columns="columns" row-key="id" :loading="loading" /></section></div><q-dialog v-model="review" persistent><q-card style="width:440px;max-width:95vw"><q-card-section><h2 class="section-heading">Confirm other-bank transfer</h2><p>{{ form.beneficiary_name }} · {{ form.target_account_number }}</p><p>{{ banks.find(b => b.value === form.target_bank_id)?.label }}</p><strong>PHP {{ Number(form.amount).toFixed(2) }}</strong><p class="page-subtitle q-mt-md">This simulated transfer needs staff settlement.</p></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" :disable="busy" v-close-popup /><q-btn color="primary" label="Confirm transfer" :loading="busy" @click="send" /></q-card-actions></q-card></q-dialog></q-page></template>
<script setup>
import { ref, onMounted, nextTick } from 'vue'
import { useQuasar } from 'quasar'
import api from '@/services/api'
const $q = useQuasar(), accounts = ref([]), banks = ref([]), rows = ref([]), loading = ref(false), busy = ref(false), review = ref(false), error = ref(''), entryForm = ref(null)
const empty = () => ({ source_account_id: null, target_bank_id: null, target_account_number: '', beneficiary_name: '', amount: '' })
const form = ref(empty()), required = v => !!v || 'Required'
const columns = [{ name: 'reference', field: 'reference_number', label: 'Reference', align: 'left' }, { name: 'recipient', field: 'beneficiary_name', label: 'Recipient', align: 'left' }, { name: 'amount', field: 'amount', label: 'PHP', format: v => Number(v).toFixed(2) }, { name: 'status', field: 'status', label: 'Status' }]
async function load () { loading.value = true; error.value = ''; try { const [a,b,h] = await Promise.all([api.get('/customer/accounts/'), api.get('/customer/other-banks/'), api.get('/customer/interbank-transfers/')]); accounts.value = a.data.filter(a => a.status === 'ACTIVE').map(a => ({label: a.account_number, value: a.id})); banks.value = b.data.map(b => ({label:b.bank_name,value:b.id})); rows.value = h.data } catch { error.value = 'Could not load transfers. Please refresh.' } finally { loading.value = false } }
async function send () { if (busy.value) return; busy.value = true; try { await api.post('/customer/interbank-transfers/', form.value); review.value = false; form.value = empty(); await nextTick(); entryForm.value?.resetValidation(); await load(); $q.notify({type:'positive',message:'Transfer submitted for simulated settlement'}) } catch(e) { review.value = false; error.value = e.response?.data?.detail || 'Could not submit transfer.' } finally { busy.value = false } }
onMounted(load)
</script>
